  "supportive_card_ids": ["C73", "C15", "C43", "C12", "C19", "C20", "C29", "C35", "C04", "C13", "C30", "C33", "C17", "C31"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C73", "C15", "C12", "C04", "C17"],
  "claims": [
    {
      "claim": "The query is a tryptamine derivative with a secondary aliphatic amine and a hydroxamic acid; its very low neutral fraction (0.01) and zwitterionic character predict poor passive permeability, and the closest L5 analog (M02) with the same secondary-amine plus hydroxamate motif has low Caco-2 Papp A→B (0.97×10^-6 cm/s) and a high efflux ratio (10.8), supporting gut-wall efflux and low absorption.",
      "card_ids": ["C73"]
    },
    {
      "claim": "DMT, a tryptamine sharing the query's indole-ethylamine core, has measured absolute oral bioavailability of about 10-15% in humans, below the 20% threshold.",
      "card_ids": ["C15", "C43"]
    },
    {
      "claim": "Sumatriptan, also a tryptamine, has consistent human oral bioavailability of 14-15% across L1 and L2 records, below the threshold.",
      "card_ids": ["C12", "C19", "C20", "C29", "C35"]
    },
    {
      "claim": "Eluxadoline, a poorly permeable ionizable molecule, has oral bioavailability of about 1% due to low gastrointestinal permeability; the query's very low neutral fraction is an analogous permeability liability, though the query is smaller and less polar.",
      "card_ids": ["C04", "C13", "C30", "C33"]
    },
    {
      "claim": "Agomelatine provides an additional low-oral-bioavailability context (under 5%), though it is structurally less similar to the query.",
      "card_ids": ["C17", "C31"]
    },
    {
      "claim": "The L5 tertiary-amine hydroxamate analog (M03) has high Papp A→B (7.04×10^-6 cm/s) and no significant efflux, but this does not transfer to the query because the query contains a secondary amine, matching the low-permeability/high-efflux M02 rather than M03.",
      "card_ids": ["C77", "C73"]
    },
    {
      "claim": "High-F contexts such as tadalafil and ketanserin are structurally dissimilar, while fluvastatin is borderline (24-29% in L1, 10-35% in L2) and lacks the query's basic amine plus hydroxamic acid combination; these do not outweigh the low-F tryptamine and poor-permeability analogs.",
      "card_ids": ["C01", "C11", "C21", "C26", "C02", "C10", "C25", "C28", "C36", "C44", "C03", "C06", "C07", "C14", "C37", "C40"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C73", "C77"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "No query-specific Caco-2/PAMPA or intestinal metabolism measurement is available; the closest L5 analog (M02) is a benzimidazole hydroxamate, not the query's indole.",
    "Hydroxamic acid metabolism and human first-pass extraction for the query are unmeasured.",
    "Caco-2 efflux is mechanistic evidence, not a direct F endpoint, and transferability from M02 is moderate.",
    "Fluvastatin's borderline 10-35% range leaves residual uncertainty about whether an indole-containing ionizable molecule could reach 20%."
  ],
  "decision_summary": "Predicted low (F < 20%) because the query's tryptamine core, secondary amine, and zwitterionic low-neutral-fraction character align with transferable low-F contexts (DMT 10-15%, sumatriptan 14-15%, eluxadoline ~1%) and with L5 Caco-2 evidence that a secondary-amine hydroxamate analog has low Papp (0.97×10^-6 cm/s) and high efflux ratio (10.8). The tertiary-amine analog's high permeability does not transfer because the query is a secondary amine. High-F contexts are structurally dissimilar or borderline, so the low prediction is retained and modestly strengthened."
}

